import unreal_engine as ue
from unreal_engine.classes import MaterialInterface
world = ue.get_editor_world()
rows = []
for a in world.all_actors():
    tags = []
    try:
        tags = [str(x) for x in a.Tags]
    except Exception:
        pass
    if 'Men' in tags or a in ue.editor_get_selected_actors():
        comps = []
        for c in a.get_actor_components():
            item = {'name': c.get_name(), 'class': c.get_class().get_name()}
            try:
                mesh = c.StaticMesh
                item['static_mesh'] = mesh.get_path_name() if mesh else None
            except Exception:
                pass
            try:
                item['override_materials'] = [m.get_path_name() if m else None for m in c.OverrideMaterials]
            except Exception:
                pass
            try:
                count = c.GetNumMaterials()
                item['num_materials'] = count
                item['effective_materials'] = []
                for i in range(count):
                    m = c.GetMaterial(i)
                    item['effective_materials'].append(m.get_path_name() if m else None)
            except Exception as e:
                item['material_query_error'] = str(e)
            comps.append(item)
        rows.append({'name': a.get_name(), 'label': a.get_actor_label(), 'class': a.get_class().get_name(), 'tags': tags, 'components': comps})
materials = []
for path in ['/Game/UGC/Materials/MasterMaterialInst/UI_Effect/DX_FX_11_Inst.DX_FX_11_Inst', '/Game/UMG/UI_Effect/Materials/DX_FlowLight_09.DX_FlowLight_09']:
    mat = ue.load_object(MaterialInterface, path)
    info = {'requested_path': path, 'loaded': mat is not None}
    if mat:
        info['class'] = mat.get_class().get_name()
        info['actual_path'] = mat.get_path_name()
        try:
            parent = mat.Parent
            info['parent'] = parent.get_path_name() if parent else None
            if parent:
                info['parent_class'] = parent.get_class().get_name()
                try:
                    info['parent_domain'] = int(parent.MaterialDomain)
                except Exception as e:
                    info['parent_domain_error'] = str(e)
        except Exception as e:
            info['parent_error'] = str(e)
        try:
            info['domain'] = int(mat.MaterialDomain)
        except Exception as e:
            info['domain_error'] = str(e)
    materials.append(info)
__askq_result = {'actors': rows, 'materials': materials}
